# bliss-banner.sh — Bliss launch sticker. Truecolor half-block anime art
# (no emoji), offline, random design per interactive shell. Opt out FLUX_NO_BANNER=1.
folio-banner-art() {
  # Prints one randomly picked design from ~/.config/bliss/banner/*.txt.
  # The designs carry literal \033 truecolor escapes -> rendered with printf %b.
  setopt localoptions nullglob 2>/dev/null || true
  local -a _bans
  _bans=( "$HOME"/.config/bliss/banner/*.txt )
  [[ -f "${_bans[1]}" ]] || return 0
  local _bi=$(( RANDOM % ${#_bans} + 1 ))
  case "$(cat "${_bans[$_bi]}" 2>/dev/null || true)" in
    *'\033'*) printf '%b\n' "$(cat "${_bans[$_bi]}")" ;;
    *)         cat "${_bans[$_bi]}" 2>/dev/null || true ;;
  esac
  unset _bans _bi
}
folio-banner() {
  [ "${FLUX_NO_BANNER:-0}" = "1" ] && return 0
  case $- in *i*) ;; *) return 0;; esac
  folio-banner-art
  # Header: exactly one line, "bliss@<id>" (distro id only — no host,
  # version or time). ID= from /etc/os-release; fallbacks: first word of
  # PRETTY_NAME (lowercased), then "linux".
  local _fid=""
  if [ -r /etc/os-release ]; then
    _fid="$(sed -n 's/^ID=//p' /etc/os-release 2>/dev/null | head -n 1 | tr -d '"' | tr '[:upper:]' '[:lower:]')"
    if [ -z "$_fid" ]; then
      _fid="$(sed -n 's/^PRETTY_NAME=//p' /etc/os-release 2>/dev/null | head -n 1 | tr -d '"' | awk '{print $1}' | tr '[:upper:]' '[:lower:]')"
    fi
  fi
  [ -n "$_fid" ] || _fid="linux"
  printf '%s\n' "bliss@$_fid"
  unset _fid
}
folio-banner
FOLIO_BANNER_SH

    if [ -n "$_owner" ]; then
        chown -R "$_owner" "$_home/.config/bliss" 2>/dev/null || true
    fi
    return 0
}

configure_shell_banner() {
    echo > "$PREFIX/etc/motd"
    rm -f "$PREFIX/etc/motd"

    echo "⚡ Configuring shell banner..."
    # Random truecolor anime launch sticker + minimal `bliss@<id>` header.
    _flux_write_folio_banner "$HOME"

    RCFILE="$HOME/.zshrc"
    [ -f "$RCFILE" ] || touch "$RCFILE"

    # Drop the plain auto-print fastfetch line from older runs; the banner
    # prints the sticker + one-line header itself.
    if grep -q 'fastfetch --config' "$RCFILE" 2>/dev/null; then
        grep -v '^fastfetch --config' "$RCFILE" > "${RCFILE}.folio.$$" 2>/dev/null \
            && mv -f "${RCFILE}.folio.$$" "$RCFILE" 2>/dev/null || rm -f "${RCFILE}.folio.$$"
    fi
    if ! grep -q 'folio/banner.sh' "$RCFILE" 2>/dev/null; then
        {
            printf '\n# Bliss launch sticker (random truecolor anime banner; opt out FLUX_NO_BANNER=1)\n'
            printf '[ -r "$HOME/.config/bliss/banner.sh" ] && . "$HOME/.config/bliss/banner.sh"\n'
        } >> "$RCFILE"
    fi

    echo "✅ Shell banner configured."
    echo "🐚 Setting Zsh as default shell..."
    chsh -s zsh
}

# ── Bliss Linux appearance (host Termux side) ────────────────────────────────
# Applies the terminal colors from ~/.config/bliss/appearance.env when the app
# staged one for the host bootstrap. No-op otherwise; never fatal.
apply_host_appearance() {
    ENV="$HOME/.config/bliss/appearance.env"
    [ -r "$ENV" ] || return 0
    FG=$(. "$ENV" >/dev/null 2>&1 || true; printf '%s' "${FLUX_TERM_FG:-#F4F4F5}")
    BG=$(. "$ENV" >/dev/null 2>&1 || true; printf '%s' "${FLUX_TERM_BG:-#09090B}")
    mkdir -p "$HOME/.termux" 2>/dev/null || true
    {
        printf 'foreground=%s\n' "$FG"
        printf 'background=%s\n' "$BG"
        printf 'cursor=%s\n' "$FG"
    } > "$HOME/.termux/colors.properties" 2>/dev/null || true
    if command -v termux-reload-settings >/dev/null 2>&1; then
        termux-reload-settings >/dev/null 2>&1 || true
    fi
    unset ENV FG BG
    return 0
}

# Main execution
install_ohmyzsh
set_termux_colors
install_nerd_font
configure_shell_banner
apply_host_appearance

echo ""
echo "🎉 Bliss: Termux enhancement complete!"
echo "🔄 Restart Termux to see all changes."

# Create marker file to track tweaks application
touch "$HOME/.fluxlinux/termux_tweaks.done"
am start -a android.intent.action.VIEW -d "fluxlinux://callback?result=success&name=termux_tweaks"
